      if (bestTask) {
        ready.delete(bestTask)

        const start = currentTime
        const cost = tasks.get(bestTask).cost
        const finish = start + cost

        startTimes.set(bestTask, start)
        finishTimes.set(bestTask, finish)
        worker.tasks.push(`${bestTask}@${start}-${finish}`)
        worker.freeAt = finish
        assigned = true

        // Check if any new tasks become ready
        for (const other of allNames) {
          if (finishTimes.has(other) || ready.has(other)) continue

          const otherDeps = deps.get(other) || new Set()
          let allDepsFinished = true

          for (const dep of otherDeps) {
            if (!finishTimes.has(dep)) {
              allDepsFinished = false
              break
            }
          }

          if (allDepsFinished) {
