      if (parts.length < 2) {
        return { error: `line ${lineNum}: expected dep <name> <dependency>...` }
      }

      const name = parts[1]
      const dependencies = parts.slice(2)

      allNames.add(name)
      for (const dep of dependencies) {
        allNames.add(dep)
        if (!deps.has(name)) {
          deps.set(name, new Set())
        }
        deps.get(name).add(dep)
      }
