 * Parsing and analysis of the build graph.
 */

const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

export class Failure extends Error {
  constructor(message, code) {
    super(message)
    this.failureMessage = message
    this.code = code
  }
}

export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * Parse the directives into a graph: a map from name to cost and a map from
 * name to the sorted set of its dependencies.
 */
export function parseGraph(lines) {
  const costs = new Map()
  const deps = new Map()
  const pending = [] // [name] in input order, for the unknown-task report

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const words = line.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new Failure(`line ${lineNo}: expected task <name> <cost>`, 2)
      }
      const [, name, cost] = words
      if (!NAME_RE.test(name)) {
        throw new Failure(`line ${lineNo}: invalid task name ${name}`, 2)
      }
      if (!COST_RE.test(cost)) {
        throw new Failure(`line ${lineNo}: cost must be a non-negative integer`, 2)
      }
      if (costs.has(name)) {
        throw new Failure(`line ${lineNo}: task ${name} is declared twice`, 2)
      }
      costs.set(name, Number(cost))
      if (!deps.has(name)) deps.set(name, new Set())
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new Failure(`line ${lineNo}: expected dep <name> <dependency>...`, 2)
      }
      for (let w = 1; w < words.length; w++) {
        if (!NAME_RE.test(words[w])) {
          throw new Failure(`line ${lineNo}: invalid task name ${words[w]}`, 2)
        }
        pending.push(words[w])
      }
      const name = words[1]
      if (!deps.has(name)) deps.set(name, new Set())
      const set = deps.get(name)
      for (let w = 2; w < words.length; w++) set.add(words[w])
    } else {
      throw new Failure(`line ${lineNo}: unknown directive ${directive}`, 2)
    }
  }

  for (const name of pending) {
    if (!costs.has(name)) throw new Failure(`unknown task ${name}`, 2)
  }

  // Every dependency map key is a declared task by now.
  const names = [...costs.keys()].sort()
  const sortedDeps = new Map()
  for (const name of names) {
    sortedDeps.set(name, [...(deps.get(name) || new Set())].sort())
  }
  return { names, costs, deps: sortedDeps }
}

/** The first cycle a depth-first search finds, or null. */
export function findCycle({ names, deps }) {
  const color = new Map() // undefined = white, 1 = gray, 2 = black
  for (const root of names) {
    if (color.get(root)) continue
    color.set(root, 1)
    const path = [root]
    const frames = [{ node: root, list: deps.get(root), i: 0 }]
    while (frames.length > 0) {
      const frame = frames[frames.length - 1]
      if (frame.i < frame.list.length) {
        const next = frame.list[frame.i++]
        const state = color.get(next)
        if (state === 1) {
          return [...path.slice(path.indexOf(next)), next]
        }
        if (state === undefined) {
          color.set(next, 1)
          path.push(next)
          frames.push({ node: next, list: deps.get(next), i: 0 })
        }
      } else {
        color.set(frame.node, 2)
        path.pop()
        frames.pop()
      }
    }
  }
  return null
}

/** Topological order (dependencies first) of an acyclic graph. */
function topoOrder({ names, deps }) {
  const dependents = new Map(names.map((n) => [n, []]))
  const remaining = new Map()
  for (const name of names) {
    remaining.set(name, deps.get(name).length)
    for (const d of deps.get(name)) dependents.get(d).push(name)
  }
  const queue = names.filter((n) => remaining.get(n) === 0)
  const order = []
  for (let i = 0; i < queue.length; i++) {
    const name = queue[i]
    order.push(name)
    for (const dependent of dependents.get(name)) {
      remaining.set(dependent, remaining.get(dependent) - 1)
      if (remaining.get(dependent) === 0) queue.push(dependent)
    }
  }
  return { order, dependents }
}

/** Start, finish and depth of every task with unlimited workers. */
export function analyse(graph) {
  const { names, costs, deps } = graph
  const { order, dependents } = topoOrder(graph)
  const start = new Map()
  const finish = new Map()
  const depth = new Map()
  for (const name of order) {
    let s = 0
    let d = 0
    for (const dep of deps.get(name)) {
      if (finish.get(dep) > s) s = finish.get(dep)
      if (depth.get(dep) + 1 > d) d = depth.get(dep) + 1
    }
    start.set(name, s)
    finish.set(name, s + costs.get(name))
    depth.set(name, d)
  }
  let total = 0
  for (const name of names) if (finish.get(name) > total) total = finish.get(name)

  // Priority: cost of the longest chain beginning at the task.
  const priority = new Map()
  for (let i = order.length - 1; i >= 0; i--) {
    const name = order[i]
    let best = 0
    for (const dependent of dependents.get(name)) {
      if (priority.get(dependent) > best) best = priority.get(dependent)
    }
    priority.set(name, costs.get(name) + best)
  }

  return { start, finish, depth, total, priority }
}

/** List scheduling onto a fixed number of workers. */
export function schedule(graph, workerCount) {
  const { names, costs, deps } = graph
  const { priority } = analyse(graph)
  const workers = []
  for (let i = 0; i < workerCount; i++) workers.push({ freeAt: 0, runs: [] })

  const finish = new Map()
  const pending = new Set(names)
  let now = 0
  let makespan = 0

  while (pending.size > 0) {
    let progressed = true
    while (progressed) {
      progressed = false
      const worker = workers.find((w) => w.freeAt <= now)
      if (!worker) break
      let best = null
      for (const name of pending) {
        let ready = true
        for (const dep of deps.get(name)) {
          if (!finish.has(dep) || finish.get(dep) > now) {
            ready = false
            break
          }
        }
        if (!ready) continue
        if (
          best === null ||
          priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break
      const end = now + costs.get(best)
      worker.runs.push(`${best}@${now}-${end}`)
      worker.freeAt = end
      finish.set(best, end)
      pending.delete(best)
      if (end > makespan) makespan = end
      progressed = true
    }
    if (pending.size === 0) break
    let next = Infinity
    for (const w of workers) if (w.freeAt > now && w.freeAt < next) next = w.freeAt
    if (next === Infinity) break
    now = next
  }

  return { workers, makespan }
}
"}

