{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { Failure, splitLines, parseGraph, findCycle, analyse, schedule } from './graph.js'

const USAGE = 'usage: cli.js waves|explain|pack <workers>'

function parseArgs(argv) {
  if ((argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain'))) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw new Failure('workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: Number(argv[1]) }
  }
  throw new Failure(USAGE, 2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function render(mode, workers, graph) {
  const cycle = findCycle(graph)
  if (cycle) throw new Failure(`cycle: ${cycle.join(' -> ')}`, 3)

  const out = []
  if (mode === 'waves') {
    const { depth, total } = analyse(graph)
    const waves = []
    for (const name of graph.names) {
      const d = depth.get(name)
      while (waves.length <= d) waves.push([])
      waves[d].push(name)
    }
    for (let i = 0; i < waves.length; i++) out.push(`wave ${i}: ${waves[i].join(' ')}`)
    out.push(`total ${total}`)
  } else if (mode === 'explain') {
    const { start, finish, depth, total } = analyse(graph)
    for (const name of graph.names) {
      out.push(`${name} start=${start.get(name)} finish=${finish.get(name)} depth=${depth.get(name)}`)
    }
    out.push(`total ${total}`)
  } else {
    const result = schedule(graph, workers)
    result.workers.forEach((worker, i) => {
      out.push(`worker ${i}:${worker.runs.map((run) => ` ${run}`).join('')}`)
    })
    out.push(`makespan ${result.makespan}`)
  }
  return out.map((line) => `${line}\n`).join('')
}

function main() {
  let output
  try {
    const { mode, workers } = parseArgs(process.argv.slice(2))
    const graph = parseGraph(splitLines(readStdin()))
    output = render(mode, workers, graph)
  } catch (error) {
    if (error instanceof Failure) {
      process.stderr.write(`error: ${error.failureMessage}\n`)
      process.exit(error.code)
    }
    throw error
  }
  process.stdout.write(output)
}

main()
"}

