 */

import { readFileSync } from 'fs'

// Read all input from stdin
function readInput() {
  const buffer = readFileSync(0, 'utf8')
  return buffer.split('\n').slice(0, -1) // drop trailing empty line from newline
}

// Parse command line arguments
function parseArgs(argv) {
  if (argv.length < 3) {
    return { error: 'usage' }
  }

  const command = argv[2]

  if (command === 'waves' || command === 'explain') {
    if (argv.length !== 3) {
      return { error: 'usage' }
    }
    return { command }
  } else if (command === 'pack') {
    if (argv.length !== 4) {
      return { error: 'usage' }
    }
    const workerStr = argv[3]
    // Check if it's a valid positive integer without leading zeros
    if (!/^[1-9]\d*$/.test(workerStr) && workerStr !== '0') {
      return { error: 'workers' }
    }
    if (workerStr === '0') {
      return { error: 'workers' }
    }
    const workers = parseInt(workerStr, 10)
    if (workers < 1) {
      return { error: 'workers' }
    }
    return { command, workers }
  } else {
    return { error: 'usage' }
  }
}

// Parse graph from lines
function parseGraph(lines) {
  const tasks = new Map() // name -> { cost }
  const deps = new Map() // name -> Set of dependencies
  const allNames = new Set()

  let lineNum = 0

  for (const rawLine of lines) {
    lineNum++

    // Trim and skip empty/comment lines
    const line = rawLine.trim()
    if (!line || line.startsWith('#')) {
      continue
    }

    const parts = line.split(/\s+/)

    if (parts[0] === 'task') {
      if (parts.length !== 3) {
        return { error: `line ${lineNum}: expected task <name> <cost>` }
      }

      const name = parts[1]
      const costStr = parts[2]

      // Validate name
      if (!/^[A-Za-z0-9_.\-]+$/.test(name)) {
        return { error: `line ${lineNum}: invalid task name ${name}` }
      }

      // Validate cost
      if (!/^\d+$/.test(costStr)) {
        return { error: `line ${lineNum}: cost must be a non-negative integer` }
      }

      const cost = parseInt(costStr, 10)

      // Check for duplicate
      if (tasks.has(name)) {
        return { error: `line ${lineNum}: task ${name} is declared twice` }
      }

      tasks.set(name, { cost })
      allNames.add(name)
      if (!deps.has(name)) {
        deps.set(name, new Set())
      }
    } else if (parts[0] === 'dep') {
      if (parts.length < 2) {
        return { error: `line ${lineNum}: expected dep <name> <dependency>...` }
      }

      const name = parts[1]
      const dependencies = parts.slice(2)

      allNames.add(name)
      for (const dep of dependencies) {
        allNames.add(dep)
        if (!deps.has(name)) {
          deps.set(name, new Set())
        }
        deps.get(name).add(dep)
      }
    } else {
      return { error: `line ${lineNum}: unknown directive ${parts[0]}` }
    }
  }

  // Check all deps refer to declared tasks (in input order)
  const seenNames = new Set()
  lineNum = 0
  for (const rawLine of lines) {
    lineNum++
    const line = rawLine.trim()
    if (!line || line.startsWith('#')) {
      continue
    }
    const parts = line.split(/\s+/)
    if (parts[0] === 'task') {
      seenNames.add(parts[1])
    } else if (parts[0] === 'dep') {
      for (let i = 1; i < parts.length; i++) {
        const name = parts[i]
        if (!tasks.has(name)) {
          return { error: `unknown task ${name}` }
        }
      }
    }
  }

  return { tasks, deps, allNames }
}

// Detect cycles using DFS
function detectCycle(deps, allNames) {
  const color = new Map() // 'white', 'gray', 'black'

  function dfs(node, stack) {
    color.set(node, 'gray')
    stack.push(node)

    const nodeDeps = deps.get(node) || new Set()
    const sortedDeps = Array.from(nodeDeps).sort()

    for (const dep of sortedDeps) {
      if (!color.has(dep)) {
        color.set(dep, 'white')
      }

      if (color.get(dep) === 'gray') {
        // Back edge found, cycle detected
        const idx = stack.indexOf(dep)
        const cycle = [...stack.slice(idx), dep]
        return cycle
      } else if (color.get(dep) === 'white') {
        const cycle = dfs(dep, stack)
        if (cycle) {
          return cycle
        }
      }
    }

    stack.pop()
    color.set(node, 'black')
    return null
  }

  // Initialize colors
  for (const name of allNames) {
    color.set(name, 'white')
  }

  const sortedNames = Array.from(allNames).sort()
  for (const name of sortedNames) {
    if (color.get(name) === 'white') {
      const cycle = dfs(name, [])
      if (cycle) {
        return cycle.join(' -> ')
      }
    }
  }

  return null
}

// Calculate waves and start/finish times with unlimited workers
function calculateWaves(tasks, deps, allNames) {
  const depth = new Map()

  function getDepth(name, visited = new Set()) {
    if (depth.has(name)) {
      return depth.get(name)
    }

    if (visited.has(name)) {
      return -1 // cycle (shouldn't happen if cycle detection passed)
    }

    visited.add(name)

    const nodeDeps = deps.get(name) || new Set()
    if (nodeDeps.size === 0) {
      depth.set(name, 0)
      return 0
    }

    let maxDepth = -1
    for (const dep of nodeDeps) {
      const depDepth = getDepth(dep, new Set(visited))
      if (depDepth === -1) {
        return -1
      }
      maxDepth = Math.max(maxDepth, depDepth)
    }

    const d = maxDepth + 1
    depth.set(name, d)
    return d
  }

  for (const name of allNames) {
    getDepth(name)
  }

  // Build waves
  const waves = new Map()
  for (const name of allNames) {
    const d = depth.get(name)
    if (!waves.has(d)) {
      waves.set(d, [])
    }
    waves.get(d).push(name)
  }

  for (const taskList of waves.values()) {
    taskList.sort()
  }

  // Calculate start/finish times
  const startFinish = new Map()

  function getStart(name) {
    const nodeDeps = deps.get(name) || new Set()
    let maxFinish = 0

    for (const dep of nodeDeps) {
      const finish = getFinish(dep)
      maxFinish = Math.max(maxFinish, finish)
    }

    return maxFinish
  }

  function getFinish(name) {
    if (startFinish.has(name)) {
      return startFinish.get(name).finish
    }

    const start = getStart(name)
    const cost = tasks.get(name).cost
    const finish = start + cost

    startFinish.set(name, { start, finish })
    return finish
  }

  for (const name of allNames) {
    getFinish(name)
  }

  return { waves, depth, startFinish }
}

// Waves command
function waves(tasks, deps, allNames) {
  const { waves: waveMap, startFinish } = calculateWaves(tasks, deps, allNames)

  const output = []

  const maxWave = Math.max(...Array.from(waveMap.keys()), -1)
  for (let i = 0; i <= maxWave; i++) {
    const taskList = waveMap.get(i) || []
    output.push(`wave ${i}: ${taskList.join(' ')}`)
  }

  let total = 0
  if (allNames.size > 0) {
    for (const name of allNames) {
      total = Math.max(total, startFinish.get(name).finish)
    }
  }

  output.push(`total ${total}`)

  return output.join('\n') + '\n'
}

// Explain command
function explain(tasks, deps, allNames) {
  const { depth, startFinish } = calculateWaves(tasks, deps, allNames)

  const output = []

  const sortedNames = Array.from(allNames).sort()
  for (const name of sortedNames) {
    const { start, finish } = startFinish.get(name)
    const d = depth.get(name)
    output.push(`${name} start=${start} finish=${finish} depth=${d}`)
  }

  let total = 0
  if (allNames.size > 0) {
    for (const name of allNames) {
      total = Math.max(total, startFinish.get(name).finish)
    }
  }

  output.push(`total ${total}`)

  return output.join('\n') + '\n'
}

// Calculate task priorities (longest chain cost from task)
function calculatePriorities(tasks, deps, allNames) {
  const priorities = new Map()
  const memo = new Map()

  function getPriority(name) {
    if (memo.has(name)) {
      return memo.get(name)
    }

    const cost = tasks.get(name).cost

    // Find all tasks that depend on this one
    let maxDependentPriority = 0
    for (const other of allNames) {
      const otherDeps = deps.get(other) || new Set()
      if (otherDeps.has(name)) {
        maxDependentPriority = Math.max(maxDependentPriority, getPriority(other))
      }
    }

    const priority = cost + maxDependentPriority
    memo.set(name, priority)
    return priority
  }

  for (const name of allNames) {
    getPriority(name)
  }

  return memo
}

// Pack command - simulate scheduling on workers
function pack(tasks, deps, allNames, workerCount) {
  const priorities = calculatePriorities(tasks, deps, allNames)

  // Track worker states
  const workers = Array(workerCount)
    .fill(null)
    .map(() => ({
      freeAt: 0,
      tasks: []
    }))

  // Track scheduled tasks: task -> { start, finish }
  const scheduled = new Map()

  let currentTime = 0

  while (scheduled.size < allNames.size) {
    // Find ready tasks: all dependencies have finished at or before currentTime
    const ready = new Set()
    for (const name of allNames) {
      if (scheduled.has(name)) continue

      const nodeDeps = deps.get(name) || new Set()
      let allDepsFinished = true

      for (const dep of nodeDeps) {
        if (!scheduled.has(dep) || scheduled.get(dep).finish > currentTime) {
          allDepsFinished = false
          break
        }
      }

      if (allDepsFinished) {
        ready.add(name)
      }
    }

    // Find free workers at current time
    const freeWorkers = workers
      .map((w, i) => ({ index: i, worker: w }))
      .filter(({ worker }) => worker.freeAt <= currentTime)
      .sort((a, b) => a.index - b.index)

    // Assign ready tasks to free workers
    let assigned = false

    for (const { index, worker } of freeWorkers) {
      if (ready.size === 0) break

      // Find task with highest priority, break ties by ascending name
      let bestTask = null
      let bestPriority = -Infinity

      for (const task of ready) {
        const priority = priorities.get(task)
        if (
          priority > bestPriority ||
          (priority === bestPriority && (bestTask === null || task < bestTask))
        ) {
          bestTask = task
          bestPriority = priority
        }
      }

      if (bestTask) {
        ready.delete(bestTask)

        const start = currentTime
        const cost = tasks.get(bestTask).cost
        const finish = start + cost

        scheduled.set(bestTask, { start, finish })
        worker.tasks.push(`${bestTask}@${start}-${finish}`)
        worker.freeAt = finish
        assigned = true
      }
    }

    if (scheduled.size >= allNames.size) {
      break
    }

    if (!assigned) {
      // Advance time to next worker free event (only future events)
      let nextTime = Infinity
      for (const { finish } of scheduled.values()) {
        if (finish > currentTime) {
          nextTime = Math.min(nextTime, finish)
        }
      }

      if (nextTime === Infinity) {
        break
      }

      currentTime = nextTime
    }
  }

  const output = []

  for (let i = 0; i < workerCount; i++) {
    const worker = workers[i]
    if (worker.tasks.length === 0) {
      output.push(`worker ${i}:`)
    } else {
      output.push(`worker ${i}: ${worker.tasks.join(' ')}`)
    }
  }

  let makespan = 0
  if (allNames.size > 0) {
    for (const { finish } of scheduled.values()) {
      makespan = Math.max(makespan, finish)
    }
  }

  output.push(`makespan ${makespan}`)

  return output.join('\n') + '\n'
}

// Main
function main() {
  const args = parseArgs(process.argv)

  if (args.error) {
    if (args.error === 'usage') {
      process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
    } else if (args.error === 'workers') {
      process.stderr.write('error: workers must be a positive integer\n')
    }
    process.exit(2)
  }

  const lines = readInput()
  const result = parseGraph(lines)

  if (result.error) {
    process.stderr.write(`error: ${result.error}\n`)
    process.exit(2)
  }

  const { tasks, deps, allNames } = result

  // Check for cycles
  const cycle = detectCycle(deps, allNames)
  if (cycle) {
    process.stderr.write(`error: cycle: ${cycle}\n`)
    process.exit(3)
  }

  let output

  if (args.command === 'waves') {
    output = waves(tasks, deps, allNames)
  } else if (args.command === 'explain') {
    output = explain(tasks, deps, allNames)
  } else if (args.command === 'pack') {
    output = pack(tasks, deps, allNames, args.workers)
  }

  process.stdout.write(output)
}

